<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigHostVO;

trait SmtpOutboundConfigHostAttributeHolder
{
    protected SmtpOutboundConfigHostVO|string|null $host = null;
    protected bool $hostAssigned = false;

    public function getHostOrCurrent(SmtpOutboundConfigHostVO $host): SmtpOutboundConfigHostVO
    {
        if ($this->hostAssigned) {
            \assert(null !== $this->host);
            return SmtpOutboundConfigHostVO::from($this->host);
        } else {
            return $host;
        }
    }
    public function hostTryBuildInitial(ConstraintFailList $error): ?SmtpOutboundConfigHostVO
    {
        return  SmtpOutboundConfigHostVO::tryFrom($this->hostAssigned ? $this->host : null, $error);
    }
    public function host(SmtpOutboundConfigHostVO|string $host): static
    {
        $this->host = $host;
        $this->hostAssigned = true;
        return $this;
    }
    public function getHost(): ?string
    {
        return $this->host instanceof SmtpOutboundConfigHostVO ? $this->host->value() : $this->host;
    }
    public function isHostAssigned(): bool
    {
        return $this->hostAssigned;
    }
    public function writeHostTo(mixed $att): void
    {
        if ($this->hostAssigned) {
            \assert(null !== $this->host);
            $att->host($this->host);
        }
    }
    public function readHostFrom(mixed $att): void
    {
        if ($att->isHostAssigned()) {
            $host = $att->getHost();
            \assert(null !== $host);
            $this->host($host);
        }
    }
    public function unsetHost(): static
    {
        $this->hostAssigned = false;
        return $this;
    }
    protected function withDefaultHost(): void
    {
    }
    protected function withAssertedHostRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->hostAssigned = $this->hostAssigned) {
            $value->host = SmtpOutboundConfigHostVO::tryFrom($this->host, $errorsList);
        }
    }
}
